    {"folder": "Linked_List", "filename": "03_reorder_list.py", "title": "Reorder List", "code": 'class Solution:\n    def reorderList(self, head) -> None:\n        slow, fast = head, head.next\n        while fast and fast.next:\n            slow = slow.next\n            fast = fast.next.next\n        second = slow.next\n        slow.next = None\n        prev = None\n        while second:\n            tmp = second.next\n            second.next = prev\n            prev = second\n            second = tmp\n        first, second = head, prev\n        while second:\n            tmp1, tmp2 = first.next, second.next\n            first.next = second\n            second.next = tmp1\n            first = tmp1\n            second = tmp2\n'},
    {"folder": "Linked_List", "filename": "04_remove_nth_node_from_end_of_list.py", "title": "Remove Nth Node From End of List", "code": 'class ListNode:\n    def __init__(self, val=0, next=None): self.val = val; self.next = next\nclass Solution:\n    def removeNthFromEnd(self, head, n: int):\n        dummy = ListNode(0, head)\n        left = dummy\n        right = head\n        while n > 0:\n            right = right.next\n            n -= 1\n        while right:\n            left = left.next\n            right = right.next\n        left.next = left.next.next\n        return dummy.next\n'},
    {"folder": "Linked_List", "filename": "05_copy_list_with_random_pointer.py", "title": "Copy List with Random Pointer", "code": 'class Node:\n    def __init__(self, x: int, next=None, random=None): self.val = int(x); self.next = next; self.random = random\nclass Solution:\n    def copyRandomList(self, head):\n        oldToCopy = {None: None}\n        cur = head\n        while cur:\n            oldToCopy[cur] = Node(cur.val)\n            cur = cur.next\n        cur = head\n        while cur:\n            copy = oldToCopy[cur]\n            copy.next = oldToCopy[cur.next]\n            copy.random = oldToCopy[cur.random]\n            cur = cur.next\n        return oldToCopy[head]\n'},
