    {"folder": "Trees", "filename": "03_diameter_of_binary_tree.py", "title": "Diameter of Binary Tree", "code": 'class Solution:\n    def diameterOfBinaryTree(self, root) -> int:\n        res = 0\n        def dfs(root):\n            nonlocal res\n            if not root:\n                return 0\n            left = dfs(root.left)\n            right = dfs(root.right)\n            res = max(res, left + right)\n            return 1 + max(left, right)\n        dfs(root)\n        return res\n'},
    {"folder": "Trees", "filename": "04_balanced_binary_tree.py", "title": "Balanced Binary Tree", "code": 'class Solution:\n    def isBalanced(self, root) -> bool:\n        def dfs(root):\n            if not root:\n                return [True, 0]\n            left, right = dfs(root.left), dfs(root.right)\n            balanced = left[0] and right[0] and abs(left[1] - right[1]) <= 1\n            return [balanced, 1 + max(left[1], right[1])]\n        return dfs(root)[0]\n'},
    {"folder": "Trees", "filename": "05_same_tree.py", "title": "Same Tree", "code": 'class Solution:\n    def isSameTree(self, p, q) -> bool:\n        if not p and not q:\n            return True\n        if not p or not q or p.val != q.val:\n            return False\n        return self.isSameTree(p.left, q.left) and self.isSameTree(p.right, q.right)\n'},
    {"folder": "Trees", "filename": "06_subtree_of_another_tree.py", "title": "Subtree of Another Tree", "code": 'class Solution:\n    def isSubtree(self, s, t) -> bool:\n        if not t:\n            return True\n        if not s:\n            return False\n        if self.sameTree(s, t):\n            return True\n        return self.isSubtree(s.left, t) or self.isSubtree(s.right, t)\n    def sameTree(self, s, t):\n        if not s and not t:\n            return True\n        if s and t and s.val == t.val:\n            return self.sameTree(s.left, t.left) and self.sameTree(s.right, t.right)\n        return False\n'},
