    {"folder": "Trees", "filename": "08_binary_tree_level_order_traversal.py", "title": "Binary Tree Level Order Traversal", "code": 'import collections\nclass Solution:\n    def levelOrder(self, root):\n        res = []\n        q = collections.deque()\n        if root:\n            q.append(root)\n        while q:\n            val = []\n            for i in range(len(q)):\n                node = q.popleft()\n                val.append(node.val)\n                if node.left:\n                    q.append(node.left)\n                if node.right:\n                    q.append(node.right)\n            res.append(val)\n        return res\n'},
    {"folder": "Trees", "filename": "09_binary_tree_right_side_view.py", "title": "Binary Tree Right Side View", "code": 'import collections\nclass Solution:\n    def rightSideView(self, root):\n        res = []\n        q = collections.deque([root] if root else [])\n        while q:\n            rightSide = None\n            for i in range(len(q)):\n                node = q.popleft()\n                if node:\n                    rightSide = node\n                    q.append(node.left)\n                    q.append(node.right)\n            if rightSide:\n                res.append(rightSide.val)\n        return res\n'},
    {"folder": "Trees", "filename": "10_count_good_nodes_in_binary_tree.py", "title": "Count Good Nodes in Binary Tree", "code": 'class Solution:\n    def goodNodes(self, root) -> int:\n        def dfs(node, maxVal):\n            if not node:\n                return 0\n            res = 1 if node.val >= maxVal else 0\n            maxVal = max(maxVal, node.val)\n            res += dfs(node.left, maxVal)\n            res += dfs(node.right, maxVal)\n            return res\n        return dfs(root, root.val)\n'},
